examples.question_text:
$JKLM$ is a parallelogram with $\overrightarrow{JK}=\underset{\sim}{u}$ and $\overrightarrow{KL}=\underset{\sim}{v}$.
Find $\overrightarrow{JL}$ and $\overrightarrow{LJ}$ in terms of $\underset{\sim}{u}$ and $\underset{\sim}{v}$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\coordinate (J) at (0,0);\coordinate (K) at (3,0);\coordinate (L) at (4,2);\coordinate (M) at (1,2);
\draw[black] (K)--(L)--(M)--(J);
\draw[black,->,thick] (J)--(K) node[midway,below] {$\underset{\sim}{u}$};
\draw[black,->,thick] (K)--(L) node[midway,right] {$\underset{\sim}{v}$};
\path (J) node[below left] {$J$} (K) node[below right] {$K$} (L) node[above right] {$L$} (M) node[above left] {$M$};
\end{tikzpicture}
[/tikz]

examples.solution_text:
Follow the path from $J$ through $K$ to $L$, then reverse it.
$\begin{aligned}\overrightarrow{JL}&=\overrightarrow{JK}+\overrightarrow{KL}\\\overrightarrow{JL}&=\underset{\sim}{u}+\underset{\sim}{v}\end{aligned}$
$\begin{aligned}\overrightarrow{LJ}&=-\overrightarrow{JL}\\\overrightarrow{LJ}&=-\underset{\sim}{u}-\underset{\sim}{v}\end{aligned}$
[tikz]
\begin{tikzpicture}[every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\definecolor{result}{HTML}{268CFF}
\coordinate (J) at (0,0);\coordinate (K) at (3,0);\coordinate (L) at (4,2);\coordinate (M) at (1,2);
\draw[black] (J)--(K)--(L)--(M)--cycle;
\draw[black,->,thick] (J)--(K) node[midway,below] {$\underset{\sim}{u}$};
\draw[black,->,thick] (K)--(L) node[midway,right] {$\underset{\sim}{v}$};
\draw[result,->,thick] (J)--(L) node[midway,above left,text=result] {$\underset{\sim}{u}+\underset{\sim}{v}$};
\path (J) node[below left] {$J$} (K) node[below right] {$K$} (L) node[above right] {$L$} (M) node[above left] {$M$};
\end{tikzpicture}
[/tikz]

examples.question_text:
Two vectors start at $T$, with $\overrightarrow{TU}=\underset{\sim}{p}$ and $\overrightarrow{TV}=\underset{\sim}{q}$.
Find $\overrightarrow{UV}$ in terms of $\underset{\sim}{p}$ and $\underset{\sim}{q}$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\coordinate (T) at (0,0);\coordinate (U) at (3,0);\coordinate (V) at (1,2);
\draw[black,->,thick] (T)--(U) node[midway,below] {$\underset{\sim}{p}$};
\draw[black,->,thick] (T)--(V) node[midway,left] {$\underset{\sim}{q}$};
\path (T) node[below left] {$T$} (U) node[right] {$U$} (V) node[above] {$V$};
\end{tikzpicture}
[/tikz]

examples.solution_text:
Travel from $U$ back to $T$, then from $T$ to $V$.
$\begin{aligned}\overrightarrow{UT}&=-\overrightarrow{TU}\\\overrightarrow{UT}&=-\underset{\sim}{p}\end{aligned}$
$\begin{aligned}\overrightarrow{UV}&=\overrightarrow{UT}+\overrightarrow{TV}\\\overrightarrow{UV}&=-\underset{\sim}{p}+\underset{\sim}{q}\\\overrightarrow{UV}&=\underset{\sim}{q}-\underset{\sim}{p}\end{aligned}$
[tikz]
\begin{tikzpicture}[every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\definecolor{result}{HTML}{268CFF}
\coordinate (T) at (0,0);\coordinate (U) at (3,0);\coordinate (V) at (1,2);
\draw[black,->,thick] (U)--(T) node[midway,below] {$-\underset{\sim}{p}$};
\draw[black,->,thick] (T)--(V) node[midway,left] {$\underset{\sim}{q}$};
\draw[result,->,thick] (U)--(V) node[midway,above right,text=result] {$\underset{\sim}{q}-\underset{\sim}{p}$};
\path (T) node[below left] {$T$} (U) node[right] {$U$} (V) node[above] {$V$};
\end{tikzpicture}
[/tikz]

Apply the triangle law, then the negative vector law.
$\begin{aligned}&\mathrel{\phantom{=}}\overrightarrow{EG}+\overrightarrow{GH}+\overrightarrow{HE}\\&=\overrightarrow{EH}+\overrightarrow{HE}\\&=\overrightarrow{EH}-\overrightarrow{EH}\\&=\underset{\sim}{0}\end{aligned}$
The successive vectors return to their starting point $E$, so their resultant is the zero vector.
[tikz]
\begin{tikzpicture}[every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\coordinate (E) at (0,0);\coordinate (G) at (3,0);\coordinate (H) at (1,2);
\draw[black,->,thick] (E)--(G);
\draw[black,->,thick] (G)--(H);
\draw[black,->,thick] (H)--(E);
\path (E) node[below left] {$E$} (G) node[below right] {$G$} (H) node[above] {$H$};
\end{tikzpicture}
[/tikz]

examples.question_text:
The diagram shows $\overrightarrow{AB}=\underset{\sim}{r}$, $\overrightarrow{BC}=\underset{\sim}{s}$ and $\overrightarrow{CD}=\underset{\sim}{t}$. Sketch the resultant $\overrightarrow{AD}$ and express it in terms of these vectors.
[tikz]
\begin{tikzpicture}[every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\coordinate (A) at (0,0);\coordinate (B) at (2,-1);\coordinate (C) at (4,1);\coordinate (D) at (2,3);
\draw[black,->,thick] (A)--(B) node[midway,below] {$\underset{\sim}{r}$};
\draw[black,->,thick] (B)--(C) node[midway,right] {$\underset{\sim}{s}$};
\draw[black,->,thick] (C)--(D) node[midway,above right] {$\underset{\sim}{t}$};
\path (A) node[left] {$A$} (B) node[below] {$B$} (C) node[right] {$C$} (D) node[above] {$D$};
\end{tikzpicture}
[/tikz]

examples.solution_text:
The vectors are connected tip to tail. Draw the resultant from the first tail $A$ to the final tip $D$.
$\begin{aligned}\overrightarrow{AD}&=\overrightarrow{AB}+\overrightarrow{BC}+\overrightarrow{CD}\\\overrightarrow{AD}&=\underset{\sim}{r}+\underset{\sim}{s}+\underset{\sim}{t}\end{aligned}$
[tikz]
\begin{tikzpicture}[every node/.style={font=\fontsize{10}{12}\selectfont,text=black}]
\definecolor{result}{HTML}{268CFF}
\coordinate (A) at (0,0);\coordinate (B) at (2,-1);\coordinate (C) at (4,1);\coordinate (D) at (2,3);
\draw[black,->,thick] (A)--(B) node[midway,below] {$\underset{\sim}{r}$};
\draw[black,->,thick] (B)--(C) node[midway,right] {$\underset{\sim}{s}$};
\draw[black,->,thick] (C)--(D) node[midway,above right] {$\underset{\sim}{t}$};
\draw[result,->,thick] (A)--(D) node[midway,left,text=result] {$\overrightarrow{AD}$};
\path (A) node[left] {$A$} (B) node[below] {$B$} (C) node[right] {$C$} (D) node[above] {$D$};
\end{tikzpicture}
[/tikz]
